import{c as t,W as d,j as a,n as o}from"./chunks/framework.Bl84hko2.js";const u=JSON.parse('{"title":"Proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/README.md","filePath":"proposals/README.md"}'),r={name:"proposals/README.md"};function s(n,e,i,c,l,p){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="proposals" tabindex="-1">Proposals <a class="header-anchor" href="#proposals" aria-label="Permalink to “Proposals”">​</a></h1><p>This directory holds the durable design record for one change per file.</p><p>Name each file <code>&lt;NNNN&gt;-&lt;slug&gt;.md</code>, using the next four-digit number and a kebab-case slug. Required frontmatter is <code>id: proposal.&lt;NNNN&gt;</code>, <code>title</code>, <code>authors</code> as a non-empty list, <code>status</code>, <code>pull-request</code>, and <code>supersedes</code>. Optional <code>issues</code> is a list of issue references or URLs. The normal lifecycle is <code>draft</code> → <code>awaiting-implementation</code> → <code>active-review</code> → <code>accepted</code> → <code>implemented</code>.</p><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th><th>Decided by</th><th>Phase</th></tr></thead><tbody><tr><td><code>draft</code></td><td>Being written and iterated on in the draft pull request. May carry <code>[NEEDS CLARIFICATION:</code>.</td><td>agent</td><td>2</td></tr><tr><td><code>awaiting-implementation</code></td><td>The human settled the proposal. Implementation is underway or not yet started.</td><td>human</td><td>3</td></tr><tr><td><code>active-review</code></td><td>First full pass at tests, guides and code exists; report posted and pull request marked ready.</td><td>agent</td><td>5</td></tr><tr><td><code>returned-for-revisions</code></td><td>The human requested changes. Back to implementation, or to the proposal if the design changed.</td><td>human</td><td>5 → 3 or 2</td></tr><tr><td><code>accepted</code></td><td>The human accepted the work. Vision update, merge and release are underway.</td><td>human</td><td>5</td></tr><tr><td><code>implemented</code></td><td>Merged and released.</td><td>agent</td><td>done</td></tr><tr><td><code>rejected</code></td><td>The human declined the change. Kept as record.</td><td>human</td><td>terminal</td></tr><tr><td><code>withdrawn</code></td><td>The author pulled it. Kept as record.</td><td>either</td><td>terminal</td></tr><tr><td><code>superseded</code></td><td>A later proposal replaced it.</td><td>either</td><td>terminal</td></tr></tbody></table><p><strong>Decided by</strong> is about judgement, not keystrokes. The human may ask the agent to make the edit — that is fine. What an agent must never do is decide on its own that a proposal is settled enough to implement, or that finished work is good enough to accept. An agent that can reach those two conclusions unaided is an agent approving its own work.</p><p>A proposal stays <code>draft</code> for as long as it takes. It is published to the draft pull request as soon as there is something to react to, and the human edits it there — directly, or by asking for changes — until they are satisfied. Iteration is the normal case, not a sign of a bad first draft.</p><p>History is preserved: never delete a superseded entry — mark it <code>superseded</code> and link its replacement through <code>supersedes</code>.</p>',7)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
